from sympy.matrices import MatrixBase


def _symbols(name, shape):
    if len(shape) == 1:
        return Matrix([Symbol(f"{name}[{i + 1}]", real=True) for i in range(shape[0])])
    return Matrix(shape[0], shape[1], lambda i, j: Symbol(f"{name}[{i + 1},{j + 1}]", real=True))


def _zeros(shape):
    return zeros(shape[0], 1) if len(shape) == 1 else zeros(shape[0], shape[1])


def _identity(shape):
    return eye(shape[0])


def _fill(value, shape):
    return _zeros(shape).applyfunc(lambda _: value)


def _rows(rows):
    return Matrix([list(row) for row in rows])


def _dot(a, b):
    return Add(*[x * y for x, y in zip(a, b)])


def _vecmat(v, m):
    return (v.T * m).T


def _hadamard(a, b):
    return a.multiply_elementwise(b)


def _ediv(a, b):
    return Matrix(a.shape[0], a.shape[1], lambda i, j: a[i, j] / b[i, j])


def _skew(v):
    return Matrix([[0, -v[2], v[1]], [v[2], 0, -v[0]], [-v[1], v[0], 0]])


def _at2(m, r, c):
    """Modelica `m[r, c]` for non-literal subscripts; `0` outside the matrix (as Lean's `Rumoca.at2`)."""
    if all(getattr(i, "is_Integer", False) or isinstance(i, int) for i in (r, c)):
        r, c = int(r), int(c)
        return m[r - 1, c - 1] if 1 <= r <= m.shape[0] and 1 <= c <= m.shape[1] else Integer(0)
    return Piecewise(*[(m[i, j], And(Eq(r, i + 1), Eq(c, j + 1)))
                       for i in range(m.shape[0]) for j in range(m.shape[1])], (Integer(0), true))


def _slice(v, off, step, k):
    """Modelica `v[a:s:b]` (`off = a - 1`, `k` elements), as Lean's `Rumoca.slice`."""
    return Matrix([v[off + step * i] for i in range(k)])


def _epow(v, n):
    return v.applyfunc(lambda e: e ** n)


def _comp(shape, body):
    """`{body(i, j) for i in 1:m, j in 1:n}` (1-based binders)."""
    if len(shape) == 1:
        return Matrix([body(i + 1) for i in range(shape[0])])
    return Matrix(shape[0], shape[1], lambda i, j: body(i + 1, j + 1))


def _upd(v, index, value):
    """Copy of `v` with the (1-based) element `index` replaced, as Lean's `Rumoca.upd1/2`."""
    out = Matrix(v)
    if len(index) == 1:
        out[int(index[0]) - 1] = value
    else:
        out[int(index[0]) - 1, int(index[1]) - 1] = value
    return out


def _piecewise(*pairs):
    """`Piecewise` that also selects between equally shaped matrices, element by element."""
    first = pairs[0][0]
    if isinstance(first, MatrixBase):
        return Matrix(first.shape[0], first.shape[1],
                      lambda i, j: Piecewise(*[(value[i, j], cond) for value, cond in pairs]))
    return Piecewise(*pairs)


def _at1(v, k):
    """Modelica `v[k]` for a non-literal `k`; `0` outside `1..n` (as Lean's `Rumoca.at1`)."""
    if getattr(k, "is_Integer", False) or isinstance(k, int):
        k = int(k)
        return v[k - 1] if 1 <= k <= len(v) else Integer(0)
    return Piecewise(*[(v[j], Eq(k, j + 1)) for j in range(len(v))], (Integer(0), true))



