def equations(call=_call):
    """`Equations t p u x dx y`, one entry per Lean conjunct, in order.

    `call(name, *args)` evaluates each Modelica function call site."""
    return [
        Eq(Y["q0"], sqrt((((Integer(1) - (X["qx"] ** 2)) - (X["qy"] ** 2)) - (X["qz"] ** 2))), evaluate=False),
        Eq(Y["s_x"], ((P["Kp"] * X["e_x"]) + (P["Kv"] * X["v_x"])), evaluate=False),
        Eq(Y["s_y"], ((P["Kp"] * X["e_y"]) + (P["Kv"] * X["v_y"])), evaluate=False),
        Eq(Y["s_z"], ((P["Kp"] * X["e_z"]) + (P["Kv"] * X["v_z"])), evaluate=False),
        Eq(Y["b3x"], (Integer(2) * ((X["qx"] * X["qz"]) + (Y["q0"] * X["qy"]))), evaluate=False),
        Eq(Y["b3y"], (Integer(2) * ((X["qy"] * X["qz"]) - (Y["q0"] * X["qx"]))), evaluate=False),
        Eq(Y["b3z"], (Integer(1) - (Integer(2) * ((X["qx"] ** 2) + (X["qy"] ** 2)))), evaluate=False),
        Eq(Y["T"], (((-(Y["s_x"] * Y["b3x"])) - (Y["s_y"] * Y["b3y"])) + ((P["g"] - Y["s_z"]) * Y["b3z"])), evaluate=False),
        Eq(Y["fbx"], (((-(Y["s_x"] * (Integer(1) - (Integer(2) * ((X["qy"] ** 2) + (X["qz"] ** 2)))))) - ((Y["s_y"] * Integer(2)) * ((X["qx"] * X["qy"]) + (Y["q0"] * X["qz"])))) + (((P["g"] - Y["s_z"]) * Integer(2)) * ((X["qx"] * X["qz"]) - (Y["q0"] * X["qy"])))), evaluate=False),
        Eq(Y["fby"], (((-((Y["s_x"] * Integer(2)) * ((X["qx"] * X["qy"]) - (Y["q0"] * X["qz"])))) - (Y["s_y"] * (Integer(1) - (Integer(2) * ((X["qx"] ** 2) + (X["qz"] ** 2)))))) + (((P["g"] - Y["s_z"]) * Integer(2)) * ((X["qy"] * X["qz"]) + (Y["q0"] * X["qx"])))), evaluate=False),
        Eq(DX["e_x"], X["v_x"], evaluate=False),
        Eq(DX["e_y"], X["v_y"], evaluate=False),
        Eq(DX["e_z"], X["v_z"], evaluate=False),
        Eq(DX["v_x"], ((Y["T"] * Y["b3x"]) + U["w_ax"]), evaluate=False),
        Eq(DX["v_y"], ((Y["T"] * Y["b3y"]) + U["w_ay"]), evaluate=False),
        Eq(DX["v_z"], (((Y["T"] * Y["b3z"]) - P["g"]) + U["w_az"]), evaluate=False),
        Eq(DX["qx"], (Rational("0.5") * (((Y["q0"] * X["p"]) + (X["qy"] * X["r"])) - (X["qz"] * X["q"]))), evaluate=False),
        Eq(DX["qy"], (Rational("0.5") * (((Y["q0"] * X["q"]) + (X["qz"] * X["p"])) - (X["qx"] * X["r"]))), evaluate=False),
        Eq(DX["qz"], (Rational("0.5") * (((Y["q0"] * X["r"]) + (X["qx"] * X["q"])) - (X["qy"] * X["p"]))), evaluate=False),
        Eq(DX["p"], ((P["kw"] * ((-((P["kR"] / P["g"]) * Y["fby"])) - X["p"])) + U["w_p"]), evaluate=False),
        Eq(DX["q"], ((P["kw"] * (((P["kR"] / P["g"]) * Y["fbx"]) - X["q"])) + U["w_q"]), evaluate=False),
        Eq(DX["r"], ((P["kw"] * ((-((Integer(2) * P["kpsi"]) * X["qz"])) - X["r"])) + U["w_r"]), evaluate=False),
    ]


